  function matchSticker(value) { const needle = String(value || "").trim().toLowerCase(); if (!needle) return null; return (state.stickers || []).find(item => [item.label, item.emoji].filter(Boolean).some(text => { const candidate = String(text).trim().toLowerCase(); return candidate === needle || candidate.includes(needle) || needle.includes(candidate); })) || null; }
