  function ensureImageProviders() { const s = state.settings; if (!Array.isArray(s.imageProviders) || !s.imageProviders.length) s.imageProviders = [{ id: "image-provider-default", name: "默认图片配置", endpoint: s.imageEndpoint || "https://api.openai.com/v1", key: s.imageKey || "", model: s.imageModel || "gpt-image-1", size: s.imageSize || "1024x1024", quality: s.imageQuality || "auto", style: s.imageStyle || "" }]; if (!s.activeImageProviderId || !s.imageProviders.some(item => item.id === s.activeImageProviderId)) s.activeImageProviderId = s.imageProviders[0].id; return s.imageProviders; }
