  function mountImageProviderManager(root) { const panel = root.querySelector('[data-extension-panel="image"] .extension-card'); if (!panel || $("#image-provider-list")) return; const block = document.createElement("div"); block.className = "image-provider-manager"; block.innerHTML = `<div class="image-provider-heading"><strong>图片供应商配置</strong><div><button class="button small quiet" data-extension-action="add-image-provider"><i data-lucide="plus"></i>添加</button><button class="button small quiet" data-extension-action="duplicate-image-provider"><i data-lucide="copy"></i>复制</button><button class="icon-button danger-icon" data-extension-action="delete-image-provider" title="删除图片配置"><i data-lucide="trash-2"></i></button></div></div><div class="image-provider-list" id="image-provider-list"></div><label class="visual-field">配置名称<input class="form-input" id="image-provider-name" placeholder="例如：OpenAI 生图" /></label>`; const enabled = panel.querySelector("#image-generation-enabled")?.closest("label"); enabled?.insertAdjacentElement("afterend", block); renderImageProviderManager(); }
  async function testImageGeneration() { readImageProviderForm(); const provider = activeImageProvider(); const endpoint = String(provider?.endpoint || "").trim().replace(/\/$/, ""); const key = String(provider?.key || ""); if (!endpoint || !key) return showToast("请填写图片接口地址和 API Key", "error"); try { const response = await fetch(`${endpoint}/models`, { headers: { Authorization: `Bearer ${key}` } }); if (!response.ok) throw new Error(`HTTP ${response.status}`); showToast("图片接口凭据可用；未产生图片费用", "success"); } catch (error) { showToast(error.message || "图片接口测试失败", "error"); } }
  async function generateImage(prompt, signal) { const provider = activeImageProvider(); const endpoint = String(provider?.endpoint || "").trim().replace(/\/$/, ""); const key = String(provider?.key || "").trim(); if (!state.settings.imageGenerationEnabled) throw new Error("请先在设置中启用图片生成"); if (!endpoint || !key) throw new Error("请先配置图片生成接口和 API Key"); const styledPrompt = [provider.style, String(prompt).trim()].filter(Boolean).join("，"); const response = await fetch(`${endpoint}/images/generations`, { method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${key}` }, signal, body: JSON.stringify({ model: provider.model || "gpt-image-1", prompt: styledPrompt, size: provider.size || "1024x1024", quality: provider.quality || "auto", n: 1 }) }); if (!response.ok) throw new Error(`图片接口返回 HTTP ${response.status}`); const data = await response.json(); const item = data.data?.[0] || {}; return item.url || (item.b64_json ? `data:image/png;base64,${item.b64_json}` : ""); }
  async function searchIntoChat(query, replyAfter = true) { const chat = activeChat() || ensureChat(); if (!state.settings.webSearchEnabled) return showToast("请先在扩展能力中启用联网搜索", "error"); try { showToast("正在联网搜索…"); const result = await searchWeb(query); chat.messages.push({ id: uid("msg"), role: "user", content: formatSearchContext(result), messageType: "web_search", meta: JSON.stringify(result), createdAt: Date.now() }); chat.updatedAt = Date.now(); saveAndRender(); if (replyAfter) { const provider = providerById(chat.providerId || state.settings.activeProviderId); const role = roleById(chat.roleId); if (providerReady(provider) && !sending) { sending = true; activeRequestController = new AbortController(); try { const reply = await generateProviderReply(chat, provider, activeRequestController.signal, role, formatSearchContext(result)); chat.messages.push(...buildRoleMessages(role, chat, reply)); chat.updatedAt = Date.now(); } finally { sending = false; activeRequestController = null; saveAndRender(); } } } showToast("搜索结果已加入对话", "success"); } catch (error) { showToast(error.message || "联网搜索失败", "error"); } }
  async function generateImageIntoChat(prompt) { const chat = activeChat() || ensureChat(); const role = roleById(chat.roleId); const provider = activeImageProvider(); const userMessage = { id: uid("msg"), role: "user", content: String(prompt).trim(), messageType: "image_prompt", createdAt: Date.now() }; const pending = { id: uid("msg"), role: "assistant", speakerId: role.id, content: "正在生成图片…", messageType: "generated_image", meta: JSON.stringify({ prompt, providerId: provider?.id }), createdAt: Date.now() }; chat.messages.push(userMessage, pending); chat.updatedAt = Date.now(); saveAndRender(); try { const url = await generateImage(prompt); if (!url) throw new Error("接口没有返回图片"); pending.image = url; pending.content = provider?.style ? `${provider.style} · ${prompt}` : String(prompt); pending.meta = JSON.stringify({ prompt, providerId: provider?.id, providerName: provider?.name, model: provider?.model, size: provider?.size }); showToast("图片已生成", "success"); } catch (error) { pending.content = `图片生成失败：${error.message || "请检查接口配置"}`; pending.messageType = "text"; showToast(error.message || "图片生成失败", "error"); } finally { chat.updatedAt = Date.now(); saveAndRender(); } }
