  function persistRoleDraft() { if (!roleDraftKey || $("#role-modal")?.classList.contains("hidden")) return; const draft = readRoleFormDraft(); const serialized = JSON.stringify(draft); const hasContent = Object.entries(draft).some(([key, value]) => key !== "avatar" && (Array.isArray(value) ? value.length : String(value || "").trim())); if (hasContent && serialized !== roleDraftBaseline) { localStorage.setItem(roleDraftKey, JSON.stringify({ ...draft, savedAt: Date.now() })); const status = $("#role-draft-status"); if (status) status.textContent = `草稿已保存 · ${timeText(Date.now())}`; } else if (serialized === roleDraftBaseline) localStorage.removeItem(roleDraftKey); }
