  function renderGroupControls(chat) {
    const root = $("#chat-group-controls"); if (!root) return;
    const isGroup = chat?.group === true; root.classList.toggle("hidden", !isGroup); if (!isGroup) return;
    $("#group-auto-relay").checked = chat.groupAutoRelay !== false; $("#group-autonomous").checked = chat.groupAutonomous !== false; $("#group-reply-decision").checked = chat.groupReplyDecision !== false; $("#group-active-topics").checked = chat.groupActiveTopics !== false; $("#group-relay-rounds").value = Math.max(1, Math.min(20, Number(chat.groupRelayRounds || 6))); $("#group-reply-probability").value = Math.max(0, Math.min(100, Number(chat.groupReplyProbability ?? 70))); $("#group-topic").value = chat.groupTopic || "";
  }
  function saveGroupControls() {
    const chat = activeChat(); if (!chat?.group) return showToast("当前不是群聊", "error");
    const rounds = Number($("#group-relay-rounds")?.value || 6); const probability = Number($("#group-reply-probability")?.value || 70);
    if (!Number.isInteger(rounds) || rounds < 1 || rounds > 20 || !Number.isFinite(probability) || probability < 0 || probability > 100) return showToast("请检查接力轮数和接话概率", "error");
    chat.groupAutoRelay = $("#group-auto-relay").checked; chat.groupAutonomous = $("#group-autonomous").checked; chat.groupReplyDecision = $("#group-reply-decision").checked; chat.groupActiveTopics = $("#group-active-topics").checked; chat.groupRelayRounds = rounds; chat.groupReplyProbability = probability; chat.groupTopic = $("#group-topic").value.trim().slice(0, 300); saveAndRender(); showToast("群聊设置已保存", "success");
  }
  function groupSpeakers(chat, content) {
    const members = chatRoles(chat); if (!members.length) return [];
    const mentioned = members.filter(role => String(content || "").includes(`@${role.name}`));
    const candidates = mentioned.length ? mentioned : members;
    if (!chat.groupReplyDecision) return candidates;
    const selected = candidates.filter(() => Math.random() * 100 < Number(chat.groupReplyProbability ?? 70));
    return selected.length ? selected : [candidates[Math.floor(Math.random() * candidates.length)]];
  }
