    root.addEventListener("click", event => { const subtab = event.target.closest("[data-extension-tab]"); if (subtab) { root.querySelectorAll("[data-extension-tab]").forEach(item => item.classList.toggle("active", item === subtab)); root.querySelectorAll("[data-extension-panel]").forEach(item => item.classList.toggle("active", item.dataset.extensionPanel === subtab.dataset.extensionTab)); if (subtab.dataset.extensionTab === "image") renderImageProviderManager(); return; } const imageProviderButton = event.target.closest("[data-image-provider-id]"); if (imageProviderButton) { readImageProviderForm(); state.settings.activeImageProviderId = imageProviderButton.dataset.imageProviderId; applyImageProviderToLegacy(); saveState(); renderImageProviderManager(); return; } const action = event.target.closest("[data-extension-action]")?.dataset.extensionAction; if (action === "save") { if (root.querySelector('[data-extension-panel="image"]')?.classList.contains("active")) readImageProviderForm(); save(); } if (action === "add-mcp") { state.mcpServers = [...(state.mcpServers || []), { id: uid("mcp"), name: `服务 ${state.mcpServers.length + 1}`, endpoint: "", key: "", enabled: true }]; renderMcpServers(); } if (action === "add-image-provider") { readImageProviderForm(); const item = { id: uid("image-provider"), name: `图片配置 ${ensureImageProviders().length + 1}`, endpoint: "https://api.openai.com/v1", key: "", model: "gpt-image-1", size: "1024x1024", quality: "auto", style: "" }; state.settings.imageProviders.push(item); state.settings.activeImageProviderId = item.id; renderImageProviderManager(); } if (action === "duplicate-image-provider") { readImageProviderForm(); const source = activeImageProvider(); const item = { ...structuredClone(source), id: uid("image-provider"), name: `${source.name || "图片配置"} 副本` }; state.settings.imageProviders.push(item); state.settings.activeImageProviderId = item.id; renderImageProviderManager(); } if (action === "delete-image-provider") { const providers = ensureImageProviders(); if (providers.length <= 1) return showToast("至少需要保留一个图片配置", "error"); const source = activeImageProvider(); if (confirm(`删除图片配置“${source.name || "未命名"}”？`)) { state.settings.imageProviders = providers.filter(item => item.id !== source.id); state.settings.activeImageProviderId = state.settings.imageProviders[0].id; renderImageProviderManager(); } } if (action === "test-search") testWebSearch(); if (action === "test-image") testImageGeneration(); if (action === "test-visual") testVisualAux(); });
