  function renderMcpServers() { const root = $("#mcp-server-list"); if (!root) return; root.innerHTML = (state.mcpServers || []).map(item => `<div class="mcp-server-row"><input class="form-input" data-mcp-id="${esc(item.id)}" data-mcp-field="name" value="${esc(item.name || "")}" placeholder="服务名称" /><input class="form-input" data-mcp-id="${esc(item.id)}" data-mcp-field="endpoint" value="${esc(item.endpoint || "")}" placeholder="https://.../mcp" /><input class="form-input" data-mcp-id="${esc(item.id)}" data-mcp-field="key" value="${esc(item.key || "")}" type="password" placeholder="可选密钥" /><label><input type="checkbox" data-mcp-id="${esc(item.id)}" data-mcp-field="enabled" ${item.enabled !== false ? "checked" : ""} />启用</label><button class="icon-button" data-mcp-id="${esc(item.id)}" data-mcp-test="true" title="测试服务"><i data-lucide="radio"></i></button><button class="icon-button" data-mcp-id="${esc(item.id)}" data-mcp-fetch="true" title="获取工具列表"><i data-lucide="list"></i></button><button class="icon-button danger-icon" data-mcp-id="${esc(item.id)}" data-mcp-remove="true" title="删除服务"><i data-lucide="trash-2"></i></button></div>`).join("") || `<div class="migration-empty">还没有 MCP 服务。</div>`; root.querySelectorAll("[data-mcp-remove]").forEach(button => button.addEventListener("click", () => { state.mcpServers = (state.mcpServers || []).filter(item => item.id !== button.dataset.mcpId); renderMcpServers(); })); root.querySelectorAll("[data-mcp-test]").forEach(button => button.addEventListener("click", () => testMcpServer(button.dataset.mcpId))); root.querySelectorAll("[data-mcp-fetch]").forEach(button => button.addEventListener("click", () => fetchMcpTools(button.dataset.mcpId))); iconRefresh(); }
  async function testMcpServer(id) { const item = (state.mcpServers || []).find(row => row.id === id); if (!item?.endpoint) return showToast("请先填写 MCP 服务地址", "error"); try { const headers = { Accept: "application/json, text/event-stream" }; if (item.key) headers.Authorization = `Bearer ${item.key}`; const response = await fetch(item.endpoint, { method: "GET", headers }); if (!response.ok && ![405, 406].includes(response.status)) throw new Error(`HTTP ${response.status}`); showToast(`${item.name || "MCP 服务"} 地址可访问`, "success"); } catch (error) { showToast(error.message || "MCP 服务连接失败", "error"); } }
  async function fetchMcpTools(id) { const item = (state.mcpServers || []).find(row => row.id === id); if (!item?.endpoint) return showToast("请先填写 MCP 服务地址", "error"); try { const headers = { "Content-Type": "application/json", Accept: "application/json, text/event-stream" }; if (item.key) headers.Authorization = `Bearer ${item.key}`; const response = await fetch(item.endpoint, { method: "POST", headers, body: JSON.stringify({ jsonrpc: "2.0", id: Date.now(), method: "tools/list", params: {} }) }); if (!response.ok) throw new Error(`HTTP ${response.status}`); const data = await response.json(); item.tools = Array.isArray(data.result?.tools) ? data.result.tools : Array.isArray(data.tools) ? data.tools : []; saveState(); renderMcpServers(); showToast(`已获取 ${item.tools.length} 个 MCP 工具`, "success"); } catch (error) { showToast(error.message || "MCP 工具列表获取失败", "error"); } }
  async function callMcpTool(serverId, toolName, args) { if (state.settings.mcpEnabled === false) return showToast("MCP 工具已关闭", "error"); const item = (state.mcpServers || []).find(row => row.id === serverId); if (!item?.endpoint || !toolName) return showToast("MCP 工具配置不完整", "error"); try { const headers = { "Content-Type": "application/json", Accept: "application/json, text/event-stream" }; if (item.key) headers.Authorization = `Bearer ${item.key}`; const response = await fetch(item.endpoint, { method: "POST", headers, body: JSON.stringify({ jsonrpc: "2.0", id: Date.now(), method: "tools/call", params: { name: toolName, arguments: args } }) }); if (!response.ok) throw new Error(`HTTP ${response.status}`); const data = await response.json(); const result = data.result || data; const chat = activeChat() || ensureChat(); chat.messages.push({ id: uid("msg"), role: "user", content: `${item.name || "MCP"} · ${toolName}`, messageType: "mcp_call", meta: JSON.stringify({ server: item.name, tool: toolName, arguments: args, result }), createdAt: Date.now() }); chat.updatedAt = Date.now(); saveAndRender(); showToast("MCP 工具结果已加入聊天", "success"); } catch (error) { showToast(error.message || "MCP 工具调用失败", "error"); } }
  function applyExperimentalUi() { document.documentElement.classList.toggle("experimental-input-glass", state.settings.experimentalInputGlass === true); document.documentElement.classList.toggle("experimental-top-transparent", state.settings.experimentalTopTransparent === true); document.documentElement.classList.toggle("experimental-glass-ui", state.settings.experimentalGlassUi === true); document.documentElement.style.setProperty("--glass-opacity", `${Math.max(30, Math.min(100, Number(state.settings.experimentalGlassOpacity || 78)))}%`); }
  function connectionRoleOptions(selected = "") { return `<option value="">未绑定角色</option>${state.roles.map(role => `<option value="${esc(role.id)}" ${role.id === selected ? "selected" : ""}>${esc(role.name)}</option>`).join("")}`; }
  function connectionChatOptions(selected = "") { return `<option value="">按联系人自动新建会话</option>${state.chats.filter(chat => !chat.archived).map(chat => `<option value="${esc(chat.id)}" ${chat.id === selected ? "selected" : ""}>${esc(chat.title || "新的对话")} · ${esc(roleById(chat.roleId)?.name || "角色")}</option>`).join("")}`; }
  function connectionStatus(item) { if (item.enabled === false) return "已暂停"; if (item.lastError) return "连接异常"; return item.status || "待测试"; }
  function connectionCard(kind, item) {
    const isWx = kind === "weixin"; const secretLabel = isWx ? "代理 Token（可选）" : "AppSecret"; const title = isWx ? "微信连接" : "QQ Bot";
    return `<article class="connection-card" data-connection-card="${kind}" data-connection-id="${esc(item.id)}"><div class="connection-card-head"><div><strong>${esc(item.name || title)}</strong><span>${esc(connectionStatus(item))}${item.roleId ? ` · ${esc(roleById(item.roleId)?.name || "未找到角色")}` : " · 未绑定角色"}</span></div><label class="mini-check"><input type="checkbox" data-connection-field="enabled" ${item.enabled !== false ? "checked" : ""} />启用</label><button class="icon-button danger-icon" data-conn-action="delete" title="删除配置"><i data-lucide="trash-2"></i></button></div><div class="form-row"><label class="visual-field">配置名称<input class="form-input" data-connection-field="name" value="${esc(item.name || "")}" placeholder="例如：工作微信" /></label><label class="visual-field">绑定角色<select class="form-input" data-connection-field="roleId">${connectionRoleOptions(item.roleId)}</select></label></div>${isWx ? `<label class="visual-field">服务端代理地址<input class="form-input" data-connection-field="endpoint" value="${esc(item.endpoint || "")}" placeholder="https://your-domain.example/weixin" /></label><label class="visual-field">${secretLabel}<input class="form-input" type="password" autocomplete="off" data-connection-field="token" value="${esc(item.token || "")}" placeholder="留空表示代理不需要 Token" /></label>` : `<div class="form-row"><label class="visual-field">Bot AppID<input class="form-input" data-connection-field="appId" value="${esc(item.appId || "")}" placeholder="QQ 开放平台 AppID" /></label><label class="visual-field">${secretLabel}<input class="form-input" type="password" autocomplete="off" data-connection-field="appSecret" value="${esc(item.appSecret || "")}" placeholder="仅保存在当前浏览器" /></label></div><label class="visual-field">服务端代理地址<input class="form-input" data-connection-field="endpoint" value="${esc(item.endpoint || "")}" placeholder="https://your-domain.example/qqbot" /></label>`}<label class="visual-field">绑定会话<select class="form-input" data-connection-field="chatId">${connectionChatOptions(item.chatId)}</select></label><div class="connection-actions"><button class="button small primary" data-conn-action="save"><i data-lucide="save"></i>保存</button><button class="button small quiet" data-conn-action="test"><i data-lucide="radio"></i>测试代理</button><button class="button small quiet" data-conn-action="sync"><i data-lucide="refresh-cw"></i>同步消息</button>${isWx ? `<button class="button small quiet" data-conn-action="import"><i data-lucide="file-up"></i>导入微信历史</button>` : ""}<span class="connection-feedback">${esc(item.lastError || item.lastTest || "")}</span></div><p class="connection-capability">网页端不会在关闭页面后后台接收消息；真实收发需要你自己的服务端代理，并正确配置 CORS。${!isWx ? " AppSecret 仅保存在当前浏览器，不等同于系统安全存储。" : ""}</p></article>`;
  }
