  function squareRelativeTime(seconds) { const time = Number(seconds || 0) * 1000; if (!time) return ""; const diff = Date.now() - time; if (diff < 60_000) return "刚刚"; if (diff < 3_600_000) return `${Math.floor(diff / 60_000)} 分钟前`; if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)} 小时前`; if (diff < 14 * 86_400_000) return `${Math.floor(diff / 86_400_000)} 天前`; return new Date(time).toLocaleDateString("zh-CN"); }
